previewCss:
.darma-loader-darma-b13-git-branch-merge { --accent: var(--loader-color, #f97316); --accent-2: var(--loader-secondary-color, #6366f1); width: var(--loader-size, 116px); height: calc(var(--loader-size, 116px) * .62); position: relative; }
.darma-loader-darma-b13-git-branch-merge::before { content: ''; position: absolute; left: 5%; top: 66%; width: 90%; height: 5%; border-radius: 999px; background: var(--accent-2); }
.darma-loader-darma-b13-git-branch-merge::after { content: ''; position: absolute; left: 22%; top: 20%; width: 52%; height: 50%; border: calc(var(--loader-size, 116px) * .042) solid var(--accent); border-bottom: 0; border-radius: 50% 50% 0 0 / 100% 100% 0 0; }
.darma-loader-darma-b13-git-branch-merge span { position: absolute; width: 12%; height: calc(var(--loader-size, 116px) * .12); border-radius: 50%; background: var(--accent); box-shadow: 0 0 0 calc(var(--loader-size, 116px) * .022) color-mix(in srgb, #fff 70%, var(--accent)); animation: darma-loader-darma-b13-git-branch-merge-commit calc(var(--loader-speed, 1s) * 1.8) ease-in-out infinite; }
.darma-loader-darma-b13-git-branch-merge span:nth-child(1) { left: 6%; top: 60%; background: var(--accent-2); }
.darma-loader-darma-b13-git-branch-merge span:nth-child(2) { left: 44%; top: 8%; animation-delay: calc(var(--loader-speed, 1s) * .6); }
.darma-loader-darma-b13-git-branch-merge span:nth-child(3) { left: 82%; top: 60%; background: var(--accent-2); animation-delay: calc(var(--loader-speed, 1s) * 1.2); }
@keyframes darma-loader-darma-b13-git-branch-merge-commit { 0%, 100% { opacity: .28; transform: scale(.6); } 45% { opacity: 1; transform: scale(1); } }

